<?php use Hls\Http\View as V; ?><section class="panel"><h2><?= V::escape($row['internal_ref']) ?></h2><?php if($row['status']==='DRAFT'&&$access->can('finance.invoice.edit')): ?><a class="button button-primary" href="<?= $this->url('/finance/invoice-edit?id='.(int)$row['id']) ?>">Edit Invoice</a><?php endif ?><p>Customer: <?= V::escape($row['customer_name']) ?> Â· Cabang: <?= V::escape($row['branch_name']) ?></p><p>Status: <?= V::escape($row['status']) ?> Â· Nomor resmi: <?= V::escape($row['official_number']??'-') ?> Â· Jatuh tempo: <?= V::escape($row['due_date']??'-') ?></p><?php if($row['status']==='DRAFT'&&$access->can('finance.invoice.issue')): ?><form method="post" action="<?= $this->url('/finance/invoice-issue') ?>" onsubmit="return confirm('Terbitkan invoice ini? Setelah diterbitkan, invoice tidak dapat diedit langsung.');"><?= $this->csrf() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="button button-primary" type="submit">Terbitkan Invoice</button></form><?php endif ?><table><thead><tr><th>Deskripsi</th><th>Qty</th><th>Harga</th><th>Subtotal</th></tr></thead><tbody><?php foreach($lines as $l): ?><tr><td><?= V::escape($l['description']) ?></td><td><?= V::escape($l['quantity']) ?></td><td><?= \Hls\Http\View::money($l['unit_price']) ?></td><td><?= \Hls\Http\View::money($l['line_total']) ?></td></tr><?php endforeach ?></tbody></table><p><strong>Total: <?= \Hls\Http\View::money($row['total_amount']) ?></strong></p></section>
